const stripTerminalControlSequences = (value = '') => String(value || '')
  .replace(/\u001b\][\s\S]*?(?:\u0007|\u001b\\)/g, '')
  .replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, '')
  .replace(/\u009b[0-?]*[ -/]*[@-~]/g, '')
  .replace(/\r/g, '')
  .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');

const inferRDocumentMode = (filePath = '') => /.(?:rmd|qmd)$/i.test(String(filePath || '')) ? 'rmd' : 'script';
const R_MARKDOWN_CHUNK_POLICY = 'R Markdown chunk detected: edit only the currently active chunk body; preserve both fences; return executable R code only; never change content outside it. If multiple chunks exist, do not edit any other chunk.';

const findAllRMarkdownChunks = (source = '') => {
  const text = String(source || '');
  const lines = text.split('\n');
  const chunks = [];
  let offset = 0;
  let openChunk = null;

  for (const line of lines) {
    const lineStart = offset;
    const lineEnd = lineStart + line.length;
    const chunkStart = line.match(/^\s*(`{3,}|~{3,})\s*\{\s*r(?:\s|,|})/i);
    const isChunkStart = Boolean(chunkStart);
    const isChunkEnd = openChunk
      ? new RegExp(`^\\s*${openChunk.fenceChar}{${openChunk.fenceLength},}\\s*$`).test(line)
      : false;

    if (!openChunk && isChunkStart) {
      openChunk = {
        lineFrom: lineStart,
        buttonFrom: lineEnd,
        codeStart: lineEnd + (offset < text.length ? 1 : 0),
        fenceChar: chunkStart[1][0],
        fenceLength: chunkStart[1].length
      };
    } else if (openChunk && isChunkEnd) {
      chunks.push({
        index: chunks.length + 1,
        code: text.slice(openChunk.codeStart, lineStart).trim(),
        from: openChunk.codeStart,
        to: lineStart,
        lineFrom: openChunk.lineFrom,
        buttonFrom: openChunk.buttonFrom
      });
      openChunk = null;
    }

    offset = lineEnd + 1;
  }

  return chunks;
};

const extractRMarkdownCode = (source = '') => {
  const text = String(source || '');
  const chunks = findAllRMarkdownChunks(text);
  return chunks.length > 0
    ? chunks.map((chunk) => chunk.code).filter(Boolean).join('\n\n')
    : text;
};

const rMarkdownLanguage = LRLanguage.define({
  parser: rLanguage.parser.configure({
    wrap: parseMixed((node, input) => {
      if (node.name !== 'String') return null;
      const source = input.read(node.from, node.to);
      if (!/^`\s*\{\s*r(?:\s|,|})/i.test(source)) return null;
      const firstNewline = source.indexOf('\n');
      const lastNewline = source.lastIndexOf('\n');
      if (firstNewline < 0 || lastNewline <= firstNewline) return null;
      const overlayFrom = node.from + firstNewline + 1;
      const overlayTo = node.from + lastNewline;
      if (overlayTo <= overlayFrom) return null;
      return {
        parser: rLanguage.parser,
        overlay: [{
          from: overlayFrom,
          to: overlayTo
        }]
      };
    })
  }),
  languageData: rLanguage.languageData
});

const rMarkdown = () => new LanguageSupport(rMarkdownLanguage);

class RMarkdownChunkRunWidget extends WidgetType {
  constructor(code, chunkIndex, onRun, onDelete) {
    super();
    this.code = code;
    this.chunkIndex = chunkIndex;
    this.onRun = onRun;
    this.onDelete = onDelete;
  }

  toDOM() {
    const controls = document.createElement('span');
    controls.style.cssText = [
      'display: inline-flex',
      'align-items: center',
      'gap: 4px',
      'float: right',
      'position: relative',
      'z-index: 5',
      'margin: 5px 8px 0 8px'
    ].join(';');

    const runButton = document.createElement('button');
    runButton.type = 'button';
    runButton.textContent = 'Run ▶';
    runButton.setAttribute('aria-label', 'Run R Markdown chunk');
    runButton.title = 'Run this R chunk';
    runButton.style.cssText = [
      'padding: 0 2px',
      'border: 0',
      'background: transparent',
      'color: #86efac',
      'font: 600 10px system-ui, sans-serif',
      'line-height: 14px',
      'cursor: pointer'
    ].join(';');
    runButton.addEventListener('mousedown', (event) => event.preventDefault());
    runButton.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.onRun(this.code, this.chunkIndex);
    });

    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.textContent = '×';
    deleteButton.setAttribute('aria-label', `Delete R Markdown chunk ${this.chunkIndex}`);
    deleteButton.title = 'Delete this R chunk';
    deleteButton.style.cssText = [
      'padding: 0 2px',
      'border: 0',
      'background: transparent',
      'color: #71717a',
      'font: 600 14px system-ui, sans-serif',
      'line-height: 14px',
      'cursor: pointer'
    ].join(';');
    deleteButton.addEventListener('mousedown', (event) => event.preventDefault());
    deleteButton.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      this.onDelete(this.chunkIndex);
    });

    controls.append(runButton, deleteButton);
    return controls;
  }

  eq(other) {
    return other.code === this.code && other.chunkIndex === this.chunkIndex;
  }
}

class RMarkdownChunkOutputWidget extends WidgetType {
  constructor(chunkIndex, output, plots = [], code = '', onOpenPlot = null) {
    super();
    this.chunkIndex = chunkIndex;
    this.output = output;
    this.plots = Array.isArray(plots) ? plots : [];
    this.code = code;
    this.onOpenPlot = onOpenPlot;
  }

  toDOM() {
    const container = document.createElement('div');
    container.className = 'cm-rmd-chunk-output';
    container.setAttribute('aria-label', `Output for R Markdown chunk ${this.chunkIndex}`);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'cm-rmd-chunk-output-toggle';
    toggle.textContent = '▾';
    toggle.title = 'Hide output';
    toggle.setAttribute('aria-label', 'Hide output');
    toggle.setAttribute('aria-expanded', 'true');

    const body = document.createElement('div');
    body.className = 'cm-rmd-chunk-output-body';

    const textOutputs = splitRChunkTextOutputs(this.output, this.code);
    if (textOutputs.length > 0) {
      const textRail = document.createElement('div');
      textRail.className = 'cm-rmd-chunk-text-rail';
      textOutputs.forEach((textOutput) => {
        const content = document.createElement('pre');
        content.className = 'cm-rmd-chunk-output-content';
        content.textContent = textOutput;
        textRail.appendChild(content);
      });
      body.appendChild(textRail);
    }

    const plotRail = document.createElement('div');
    plotRail.className = 'cm-rmd-chunk-plot-rail';
    this.plots.forEach((plot) => {
      const imageSource = String(plot?.url || plot?.base64 || '');
      if (!imageSource || plot?.mediaType === 'video' || plot?.mediaType === 'html') return;
      const card = document.createElement('div');
      card.className = 'cm-rmd-chunk-plot-card';
      card.title = String(plot?.title || 'Generated plot');
      card.setAttribute('role', 'button');
      card.setAttribute('tabindex', '0');
      card.setAttribute('aria-label', `Open ${String(plot?.title || 'generated plot')} in the plots gallery`);
      const image = document.createElement('img');
      image.src = imageSource;
      image.alt = String(plot?.title || 'Generated plot');
      image.loading = 'lazy';
      card.appendChild(image);
      const openPlot = (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.onOpenPlot?.(plot);
      };
      card.addEventListener('pointerdown', openPlot);
      card.addEventListener('click', (event) => {
        openPlot(event);
      });
      card.addEventListener('keydown', (event) => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        event.stopPropagation();
        this.onOpenPlot?.(plot);
      });
      plotRail.appendChild(card);
    });
    if (plotRail.childElementCount > 0) body.appendChild(plotRail);

    const toggleOutput = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const isCollapsed = body.hidden;
      body.hidden = !isCollapsed;
      body.style.display = isCollapsed ? '' : 'none';
      toggle.textContent = isCollapsed ? '▾' : '▴';
      toggle.title = isCollapsed ? 'Hide output' : 'Show output';
      toggle.setAttribute('aria-label', toggle.title);
      toggle.setAttribute('aria-expanded', String(isCollapsed));
    };
    toggle.addEventListener('pointerdown', toggleOutput);
    toggle.addEventListener('click', (event) => {
      if (event.detail !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      toggleOutput(event);
    });

    container.append(body, toggle);
    return container;
  }

  eq(other) {
    const plotKey = this.plots.map((plot) => String(plot?.id || plot?.url || plot?.base64 || '')).join('|');
    const otherPlotKey = (other.plots || []).map((plot) => String(plot?.id || plot?.url || plot?.base64 || '')).join('|');
    return other.chunkIndex === this.chunkIndex
      && other.output === this.output
      && other.code === this.code
      && plotKey === otherPlotKey;
  }
}

const splitRChunkTextOutputs = (output, code = '') => {
  const codeLines = new Set(
    String(code || '')
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
  );
  const outputs = [];
  let current = [];
  const flush = () => {
    const text = current.join('\n').replace(/^\s*\n+|\n+\s*$/g, '');
    if (text) outputs.push(text);
    current = [];
  };

  String(output || '').split(/\r?\n/).forEach((line) => {
    if (/^\s*>\s?/.test(line)) {
      flush();
      return;
    }
    const trimmed = line.trim();
    if (/^\s*\+\s?/.test(line) || /^\s*#/.test(line) || codeLines.has(trimmed)) {
      return;
    }
    current.push(line);
  });
  flush();
  return outputs;
};

const setRMarkdownChunkResults = StateEffect.define();

