const buildRMarkdownChunkOutputDecorations = (state, getChunkOutput, getChunkPlots, getChunkCode, onOpenPlot) => {
  const decorations = [];
  findAllRMarkdownChunks(state.doc.toString()).forEach((chunk) => {
    const chunkPlots = getChunkPlots?.(chunk.index) || [];
    const chunkCode = getChunkCode?.(chunk.index) || chunk.code;
    const chunkOutput = String(getChunkOutput?.(chunk.index) || '');
    const chunkTextOutputs = splitRChunkTextOutputs(chunkOutput, chunkCode);
    if (chunkTextOutputs.length === 0 && chunkPlots.length === 0) return;
    const closingLine = state.doc.lineAt(chunk.to);
    decorations.push(
      Decoration.widget({
        widget: new RMarkdownChunkOutputWidget(chunk.index, chunkOutput, chunkPlots, chunkCode, onOpenPlot),
        side: 1,
        block: true
      }).range(closingLine.to)
    );
  });
  return Decoration.set(decorations, true);
};

const createRMarkdownChunkOutputExtension = (getChunkOutput, getChunkPlots, getChunkCode, onOpenPlot) => StateField.define({
  create: (state) => buildRMarkdownChunkOutputDecorations(state, getChunkOutput, getChunkPlots, getChunkCode, onOpenPlot),
  update: (decorations, transaction) => {
    const resultEffect = transaction.effects.find((effect) => effect.is(setRMarkdownChunkResults));
    if (resultEffect) {
      return buildRMarkdownChunkOutputDecorations(
        transaction.state,
        (chunkIndex) => resultEffect.value?.outputs?.[chunkIndex],
        (chunkIndex) => resultEffect.value?.plots?.[chunkIndex],
        (chunkIndex) => resultEffect.value?.codes?.[chunkIndex],
        onOpenPlot
      );
    }
    return transaction.docChanged
      ? buildRMarkdownChunkOutputDecorations(transaction.state, getChunkOutput, getChunkPlots, getChunkCode, onOpenPlot)
      : decorations;
  },
  provide: (field) => EditorView.decorations.from(field)
});

const createRMarkdownChunkRunExtension = (onRun, onDelete, onInsert) => ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = this.buildDecorations(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.selectionSet) {
      this.decorations = this.buildDecorations(update.view);
    }
  }

  buildDecorations(view) {
    const chunks = findAllRMarkdownChunks(view.state.doc.toString());
    const decorations = chunks.flatMap((chunk) => {
      const openingLine = view.state.doc.lineAt(chunk.lineFrom);
      const closingLine = view.state.doc.lineAt(chunk.to);
      const openingLineClasses = [
        'cm-rmd-cell-start'
      ].join(' ');
      const chunkDecorations = [
        Decoration.replace({}).range(openingLine.from, openingLine.to),
        Decoration.line({
          attributes: { class: openingLineClasses }
        }).range(openingLine.from),
        Decoration.replace({}).range(closingLine.from, closingLine.to),
        Decoration.line({
          attributes: { class: 'cm-rmd-cell-end' }
        }).range(closingLine.from),
        Decoration.widget({
          widget: new RMarkdownChunkRunWidget(chunk.code, chunk.index, onRun, onDelete),
          side: 1
        }).range(chunk.buttonFrom)
      ];
      if (chunk.index < chunks.length) {
        chunkDecorations.push(
          Decoration.widget({
            widget: new RMarkdownChunkInsertWidget(chunk.index, onInsert),
            side: 1
          }).range(closingLine.to)
        );
      }
      for (let position = openingLine.to + 1; position < closingLine.from;) {
        const bodyLine = view.state.doc.lineAt(position);
        chunkDecorations.push(
          Decoration.line({
            attributes: { class: 'cm-rmd-cell-body' }
          }).range(bodyLine.from)
        );
        position = bodyLine.to + 1;
      }
      return chunkDecorations;
    }).sort((left, right) => left.from - right.from || left.to - right.to);
    return Decoration.set(decorations);
  }
}, {
  decorations: (plugin) => plugin.decorations
});

const findAllPythonNotebookCells = (source = '') => {
  const text = String(source || '');
  const lines = text.split('\n');
  const markers = [];
  let offset = 0;

  lines.forEach((line) => {
    const lineStart = offset;
    const lineEnd = lineStart + line.length;
    if (/^\s*#\s*%%(?:\s.*)?$/.test(line)) {
      markers.push({ lineFrom: lineStart, buttonFrom: lineEnd });
    }
    offset = lineEnd + 1;
  });

  return markers.map((marker, index) => {
    const nextMarker = markers[index + 1];
    const to = nextMarker ? nextMarker.lineFrom : text.length;
    return {
      index: index + 1,
      code: text.slice(marker.buttonFrom + 1, to).trim(),
      from: marker.buttonFrom + 1,
      to,
      lineFrom: marker.lineFrom,
      buttonFrom: marker.buttonFrom
    };
  });
};

const buildPythonNotebookCellInsertion = (source, cursor) => {
  const trailingNewlines = String(source).slice(0, cursor).match(/\n*$/)?.[0].length || 0;
  const from = cursor - trailingNewlines;
  const insertion = '\n\n# %%\n\n';
  return {
    from,
    insertion,
    next: `${String(source).slice(0, from)}${insertion}${String(source).slice(cursor)}`
  };
};

