const createPythonNotebookCellExtension = (onRun, onDelete, onInsert) => ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = this.buildDecorations(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.selectionSet) {
      this.decorations = this.buildDecorations(update.view);
    }
  }

  buildDecorations(view) {
    const cells = findAllPythonNotebookCells(view.state.doc.toString());
    const decorations = cells.flatMap((cell) => {
      const markerLine = view.state.doc.lineAt(cell.lineFrom);
      const cellDecorations = [
        Decoration.replace({}).range(markerLine.from, markerLine.to),
        Decoration.line({ attributes: { class: 'cm-python-cell-start' } }).range(markerLine.from),
        Decoration.widget({
          widget: new PythonNotebookCellRunWidget(cell.code, cell.index, onRun, onDelete),
          side: 1
        }).range(cell.buttonFrom)
      ];
      if (cell.index < cells.length) {
        cellDecorations.push(
          Decoration.widget({
            widget: new PythonNotebookCellInsertWidget(cell.index, onInsert),
            // Anchor the control at the next cell boundary so it does not
            // share the final code line's decoration.
            side: -1
          }).range(cell.to)
        );
      }
      const endLine = view.state.doc.lineAt(Math.max(markerLine.to, cell.to - 1));
      for (let position = markerLine.to + 1; position < cell.to;) {
        const bodyLine = view.state.doc.lineAt(position);
        cellDecorations.push(
          Decoration.line({
            attributes: {
              class: bodyLine.from === endLine.from
                ? 'cm-python-cell-body cm-python-cell-end'
                : 'cm-python-cell-body'
            }
          }).range(bodyLine.from)
        );
        position = bodyLine.to + 1;
      }
      return cellDecorations;
    });
    return Decoration.set(decorations, true);
  }
}, {
  decorations: (plugin) => plugin.decorations
});

