const parseEccDnaNumber = (value, fallback = 0) => {
  const parsed = Number.parseFloat(String(value ?? "").trim());
  return Number.isFinite(parsed) ? parsed : fallback;
};

const formatEccDnaNumber = (value) => Number(value || 0).toLocaleString();

const normalizeEccDnaLines = (value = "") => String(value || "")
  .replaceAll(String.fromCharCode(13), "")
  .split(String.fromCharCode(10))
  .map((line) => line.trim())
  .filter(Boolean);

const splitEccDnaTsvLine = (line = "") => String(line || "").split(String.fromCharCode(9));

const parseEccDnaFinderLoci = (csvData = "") => normalizeEccDnaLines(csvData).map((line, index) => {
  const cols = splitEccDnaTsvLine(line);
  if (cols.length < 3) return null;

  const isShortRead = cols.length <= 6;
  const start = parseEccDnaNumber(cols[1]);
  const end = parseEccDnaNumber(cols[2]);
  const inferredLength = Math.max(0, end - start);
  const length = isShortRead
    ? parseEccDnaNumber(cols[5], inferredLength)
    : parseEccDnaNumber(cols[6], inferredLength);
  const splitReads = isShortRead ? parseEccDnaNumber(cols[3]) : 0;
  const discordantReads = isShortRead ? parseEccDnaNumber(cols[4]) : 0;
  const circularReads = isShortRead ? splitReads + discordantReads : parseEccDnaNumber(cols[3]);
  const repeatUnits = isShortRead ? 0 : parseEccDnaNumber(cols[4]);
  const coverage = isShortRead ? 0 : parseEccDnaNumber(cols[5]);

  return {
    index,
    chromosome: cols[0] || "Unknown",
    start,
    end,
    length,
    isShortRead,
    circularReads,
    splitReads,
    discordantReads,
    repeatUnits,
    coverage,
    evidenceLabel: isShortRead ? "Split and discordant read support" : "Tandem-repeat circular read support",
    evidenceDetail: isShortRead
      ? formatEccDnaNumber(splitReads) + " split-read signal(s) and " + formatEccDnaNumber(discordantReads) + " discordant-read signal(s)"
      : formatEccDnaNumber(circularReads) + " circular read(s), " + formatEccDnaNumber(repeatUnits) + " repeat unit(s), coverage " + formatEccDnaNumber(coverage)
  };
}).filter(Boolean);

const parseEccDnaFastaEvidence = (fastaData = "") => {
  const records = [];
  let current = null;

  normalizeEccDnaLines(fastaData).forEach((line) => {
    if (line.startsWith("... [Truncated")) return;
    if (line.startsWith(">")) {
      current = { header: line, length: 0 };
      records.push(current);
      return;
    }
    if (current) current.length += line.replaceAll(" ", "").replaceAll(String.fromCharCode(9), "").length;
  });

  const totalLength = records.reduce((sum, record) => sum + record.length, 0);
  return { records, totalLength };
};

const parseEccDnaBedEvidence = (bedData = "") => {
  const regions = normalizeEccDnaLines(bedData)
    .filter((line) => !line.startsWith("... [Truncated"))
    .map(splitEccDnaTsvLine)
    .filter((cols) => cols.length >= 3)
    .map((cols, index) => ({
      index,
      chromosome: cols[0] || "Unknown",
      start: parseEccDnaNumber(cols[1]),
      end: parseEccDnaNumber(cols[2])
    }));

  return { regions };
};

const buildEccDnaFinderEvidence = (result = {}) => {
  const loci = parseEccDnaFinderLoci(result.csvData);
  const fasta = parseEccDnaFastaEvidence(result.fastaData);
  const bed = parseEccDnaBedEvidence(result.bedData);
  const totalReadSignals = loci.reduce((sum, locus) => sum + locus.circularReads, 0);
  const highConfidenceLoci = loci.filter((locus) => locus.circularReads >= 5).length;

  const status = loci.length > 0
    ? "Circular DNA detected"
    : bed.regions.length > 0
      ? "Candidate circular DNA sites found; no final loci passed filters"
      : fasta.records.length > 0
        ? (String(result.tool || '').startsWith('asm') ? "Circular sequence assembly evidence found" : "Circular sequence evidence extracted")
        : "No circular DNA evidence extracted";

  return { loci, fasta, bed, totalReadSignals, highConfidenceLoci, status };
};

