const getNextPaletteOption = (currentValue) => {
  if (!Array.isArray(PALETTE_OPTIONS) || PALETTE_OPTIONS.length === 0) {
    return { value: 'set3', label: 'Set3' };
  }
  const safeCurrentValue = String(currentValue || '').trim().toLowerCase();
  const currentIndex = PALETTE_OPTIONS.findIndex((palette) => palette.value === safeCurrentValue);
  const nextIndex = currentIndex >= 0
    ? (currentIndex + 1) % PALETTE_OPTIONS.length
    : 0;
  return PALETTE_OPTIONS[nextIndex] || PALETTE_OPTIONS[0];
};

