const DEFAULT_REGRESSION_TRAIN_PERCENT = 80;
const DEFAULT_REGRESSION_CLASSIFICATION_THRESHOLD = 0.5;
const DEFAULT_REGRESSION_STANDARDIZE_PREDICTORS = false;
const R_IDE_CONTEXT_STOPWORDS = new Set([
  'the', 'and', 'with', 'from', 'into', 'that', 'this', 'then', 'else', 'return', 'using',
  'data', 'code', 'block', 'line', 'lines', 'script', 'editor', 'please', 'update', 'change',
  'modify', 'adjust', 'improve', 'make', 'need', 'must', 'chat', 'assistant', 'function',
  'for', 'while', 'when', 'where', 'there', 'here', 'your', 'their', 'just'
]);
const REGRESSION_TRAIN_SPLIT_OPTIONS = [
  { value: 50, label: '50 / 50' },
  { value: 60, label: '60 / 40' },
  { value: 70, label: '70 / 30' },
  { value: 75, label: '75 / 25' },
  { value: 80, label: '80 / 20' },
  { value: 85, label: '85 / 15' },
  { value: 90, label: '90 / 10' }
];

const normalizeRegressionTrainPercent = (value) => {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  if (!Number.isFinite(parsed)) return DEFAULT_REGRESSION_TRAIN_PERCENT;
  const matched = REGRESSION_TRAIN_SPLIT_OPTIONS.find((option) => option.value === parsed);
  return matched ? matched.value : DEFAULT_REGRESSION_TRAIN_PERCENT;
};

const normalizeRegressionClassificationThreshold = (value) => {
  const parsed = Number.parseFloat(String(value ?? ''));
  if (!Number.isFinite(parsed)) return DEFAULT_REGRESSION_CLASSIFICATION_THRESHOLD;
  const clamped = Math.min(0.99, Math.max(0.01, parsed));
  return Math.round(clamped * 100) / 100;
};

const normalizeRegressionStandardizePredictors = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return Number.isFinite(value) ? value !== 0 : DEFAULT_REGRESSION_STANDARDIZE_PREDICTORS;
  const normalized = String(value ?? '').trim().toLowerCase();
  if (!normalized) return DEFAULT_REGRESSION_STANDARDIZE_PREDICTORS;
  if (['true', 't', '1', 'yes', 'y', 'on'].includes(normalized)) return true;
  if (['false', 'f', '0', 'no', 'n', 'off'].includes(normalized)) return false;
  return DEFAULT_REGRESSION_STANDARDIZE_PREDICTORS;
};

