const sanitizeRIdentifier = (value, fallback = '') => {
  const normalized = String(value || '')
    .trim()
    .replace(/[^A-Za-z0-9._]/g, '_')
    .replace(/^[^A-Za-z.]+/, '');
  return normalized || fallback;
};

const normalizeList = (value) => {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined) return [];
  if (typeof value === 'object') return Object.values(value);
  return [value];
};

const normalizeSheetNames = (value) => {
  const flattenValues = (input, depth = 0) => {
    if (depth > 3 || input === null || input === undefined) return [];
    if (Array.isArray(input)) {
      return input.flatMap((entry) => flattenValues(entry, depth + 1));
    }
    if (typeof input === 'object') {
      return Object.values(input).flatMap((entry) => flattenValues(entry, depth + 1));
    }
    return [input];
  };

  const seen = new Set();
  const normalized = [];
  flattenValues(value).forEach((sheetName) => {
    const safeName = String(sheetName || '').trim();
    if (!safeName) return;
    const key = safeName.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    normalized.push(safeName);
  });
  return normalized;
};

