const normalizeRowArray = (value) => {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return [value];
  return [];
};

const normalizeDatasetMetadata = (metadata = {}) => {
  let rawColumns = normalizeList(metadata?.columns).map((columnName) => String(columnName ?? ''));
  const rawRows = normalizeRowArray(metadata?.fullData);
  const metadataRowNames = normalizeList(metadata?.row_names)
    .map((rowName) => String(rowName ?? ''));
  const hasMetadataRowNames = metadataRowNames.length === rawRows.length;
  const syntheticLeadingColumn = hasMetadataRowNames
    && rawColumns.length > 0
    && /^\.\.\.1$/.test(rawColumns[0])
    && !rawColumns.includes('');

  // Keep an unnamed first field as a real dataset column. Older R/Excel
  // readers may report that field as ...1 while also returning row_names;
  // normalize that representation to the same blank column used by CSV.
  if (syntheticLeadingColumn) rawColumns = ['', ...rawColumns.slice(1)];
  const hasEmptyColumn = rawColumns.includes('');
  if (hasMetadataRowNames && !hasEmptyColumn) rawColumns = ['', ...rawColumns];

  const rows = rawRows.map((row, rowIndex) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) return row;
    const nextRow = { ...row };
    // jsonlite serializes an unnamed data-frame field as "1" in row objects
    // even though the metadata correctly keeps its empty column name.
    if (rawColumns[0] === ''
      && !Object.prototype.hasOwnProperty.call(nextRow, '')
      && Object.prototype.hasOwnProperty.call(nextRow, '1')) {
      nextRow[''] = nextRow['1'];
      delete nextRow['1'];
    }
    if (syntheticLeadingColumn) {
      const legacyValue = nextRow['...1'];
      delete nextRow['...1'];
      nextRow[''] = hasMetadataRowNames ? metadataRowNames[rowIndex] : legacyValue;
    } else if (hasMetadataRowNames && !Object.prototype.hasOwnProperty.call(nextRow, '')) {
      nextRow[''] = metadataRowNames[rowIndex];
    }
    return nextRow;
  });
  return {
    columns: rawColumns,
    rows,
    rowNames: []
  };
};

const richTextHtmlToPlainText = (html) =>
  String(html || '')
    .replace(/<\/(div|p|li|h[1-6])>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/<[^>]*>/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

