const formatAnalysisLabel = (value = '') => {
  const normalized = String(value || '').trim();
  if (!normalized) return '';
  const spaced = normalized.replace(/_/g, ' ').trim();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
};

const clampProgressPercent = (value) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.min(100, Math.round(numeric)));
};

const parseAnalysisProgressToken = (line) => {
  const text = String(line || '').trim();
  if (!text.startsWith('PROGRESS|')) return null;
  const parts = text.split('|');
  if (parts.length < 5) return null;
  return {
    percent: clampProgressPercent(parts[1]),
    pass: String(parts[2] || '').trim() || 'Pass',
    test: String(parts[3] || '').trim() || 'Step',
    path: String(parts[4] || '').trim()
  };
};

const resolvePrimaryTestLabel = (result = {}) => {
  if (!result || typeof result !== 'object') return 'Analysis test';
  if (result.one_value?.selected_test) return String(result.one_value.selected_test);
  if (result.ttest?.test_name) return String(result.ttest.test_name);
  if (result.wilcoxon?.test_name) return String(result.wilcoxon.test_name);
  if (result.anova?.test_type === 'welch') return "Welch's ANOVA";
  if (result.anova?.test_type === 'standard') return 'One-Way ANOVA';
  if (result.rm_anova) return 'Repeated Measures ANOVA';
  if (result.friedman) return 'Friedman Test';
  if (result.kruskal) return 'Kruskal-Wallis';
  if (result.mann_whitney?.test_name) return String(result.mann_whitney.test_name);
  if (result.chisq) return 'Chi-square test';
  if (result.test_type) return String(result.test_type);
  return 'Analysis test';
};

const hasPostHocResults = (result = {}) => {
  if (!result || typeof result !== 'object') return false;
  return Boolean(
    (Array.isArray(result.tukey) && result.tukey.length > 0) ||
    (Array.isArray(result.games_howell) && result.games_howell.length > 0) ||
    (Array.isArray(result.dunn) && result.dunn.length > 0) ||
    (Array.isArray(result.rm_anova_posthoc) && result.rm_anova_posthoc.length > 0) ||
    (Array.isArray(result.holm_posthoc) && result.holm_posthoc.length > 0)
  );
};

const hasShapiroViolation = (result = {}) => {
  const shapiro = result?.shapiro;
  if (!shapiro || typeof shapiro !== 'object') return false;
  return Object.values(shapiro).some((entry) => entry?.is_normal === false);
};

const resolveHomogeneityViolationState = (result = {}) => {
  if (result?.levene && typeof result.levene === 'object') {
    if (result.levene.is_homogeneous === false) return true;
    if (result.levene.is_homogeneous === true) return false;
  }
  if (result?.bartlett && typeof result.bartlett === 'object') {
    if (result.bartlett.is_homogeneous === false) return true;
    if (result.bartlett.is_homogeneous === true) return false;
  }
  return null;
};

const resolveSphericityViolationState = (result = {}) => {
  if (result?.rm_anova && typeof result.rm_anova === 'object') {
    if (result.rm_anova.sphericity_violated === true) return true;
    if (result.rm_anova.sphericity_violated === false) return false;
  }
  const checks = result?.sphericity_checks;
  if (!checks || typeof checks !== 'object') return null;
  const values = Object.values(checks);
  if (values.length === 0) return null;
  if (values.some((entry) => entry?.sphericity_violated === true)) return true;
  if (values.some((entry) => entry?.sphericity_violated === false)) return false;
  return null;
};

const buildCompletedInferentialPasses = (result = {}) => {
  const pathTaken = String(result?.path_taken || 'pending');
  const passes = [];
  const shapiroViolated = hasShapiroViolation(result);
  const homogeneityViolated = resolveHomogeneityViolationState(result);
  const sphericityViolated = resolveSphericityViolationState(result);
  if (result?.shapiro) {
    passes.push({
      key: 'normality',
      percent: 25,
      pass: 'Pass 1',
      test: shapiroViolated ? 'Shapiro-Wilk normality violated' : 'Shapiro-Wilk normality',
      path: ''
    });
  }
  if (result?.levene || result?.bartlett || result?.sphericity_checks || result?.rm_anova?.sphericity_violated !== undefined) {
    const assumptionLabels = [];
    if (homogeneityViolated === true) assumptionLabels.push('Homogeneity violated');
    else if (homogeneityViolated === false) assumptionLabels.push('Homogeneity not violated');
    if (sphericityViolated === true) assumptionLabels.push('Sphericity violated');
    else if (sphericityViolated === false) assumptionLabels.push('Sphericity not violated');
    passes.push({
      key: 'assumption',
      percent: 45,
      pass: 'Pass 2',
      test: assumptionLabels.length > 0 ? assumptionLabels.join(' • ') : 'Assumption checks',
      path: ''
    });
  }
  passes.push({
    key: 'path',
    percent: 60,
    pass: 'Pass 3',
    test: 'Path selection',
    path: pathTaken
  });
  passes.push({
    key: 'main_test',
    percent: 82,
    pass: 'Pass 4',
    test: resolvePrimaryTestLabel(result),
    path: ''
  });
  if (hasPostHocResults(result)) {
    passes.push({
      key: 'posthoc',
      percent: 94,
      pass: 'Pass 5',
      test: 'Post-hoc comparisons',
      path: ''
    });
  }
  passes.push({
    key: 'finalize',
    percent: 100,
    pass: 'Pass 6',
    test: 'Result finalized',
    path: ''
  });
  return passes;
};

