      yTickMode: resolveTickModeFromInterval(editor?.yTickInterval, editor?.yTickMode),
      xTickCount: normalizeTickCountValue(editor?.xTickCount, 6),
      yTickCount: normalizeTickCountValue(editor?.yTickCount, 6),
      xTickInterval: normalizeOptionalNumericText(editor?.xTickInterval, { positive: true }),
