const hashString = (value = '') => {
  let hash = 0;
  const input = String(value || '');
  for (let index = 0; index < input.length; index += 1) {
    hash = ((hash << 5) - hash) + input.charCodeAt(index);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
};

const clampByte = (value) => Math.max(0, Math.min(255, Math.round(Number(value) || 0)));
const clampAlpha = (value, fallback = 1) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.max(0, Math.min(1, numeric));
};

const parseHexColor = (value) => {
  const input = String(value || '').trim();
  if (!input.startsWith('#')) return null;
  if (input.length === 4 || input.length === 5) {
    const r = parseInt(input[1] + input[1], 16);
    const g = parseInt(input[2] + input[2], 16);
    const b = parseInt(input[3] + input[3], 16);
    const a = input.length === 5 ? parseInt(input[4] + input[4], 16) / 255 : 1;
    if ([r, g, b].some((channel) => Number.isNaN(channel)) || Number.isNaN(a)) return null;
    return { r, g, b, a };
  }
  if (input.length === 7 || input.length === 9) {
    const r = parseInt(input.slice(1, 3), 16);
    const g = parseInt(input.slice(3, 5), 16);
    const b = parseInt(input.slice(5, 7), 16);
    const a = input.length === 9 ? parseInt(input.slice(7, 9), 16) / 255 : 1;
    if ([r, g, b].some((channel) => Number.isNaN(channel)) || Number.isNaN(a)) return null;
    return { r, g, b, a };
  }
  return null;
};

const parseRgbColor = (value) => {
  const input = String(value || '').trim();
  const match = input.match(/^rgba?\(([^)]+)\)$/i);
  if (!match) return null;
  const parts = match[1].split(',').map((part) => part.trim());
  if (parts.length !== 3 && parts.length !== 4) return null;
  const r = Number(parts[0]);
  const g = Number(parts[1]);
  const b = Number(parts[2]);
  const a = parts.length === 4 ? Number(parts[3]) : 1;
  if ([r, g, b, a].some((channel) => !Number.isFinite(channel))) return null;
  return {
    r: clampByte(r),
    g: clampByte(g),
    b: clampByte(b),
    a: clampAlpha(a, 1)
  };
};

const parseColorValue = (value) => parseHexColor(value) || parseRgbColor(value);

const mixColors = (left, right, ratio = 0.5) => {
  const safeLeft = left || { r: 0, g: 0, b: 0, a: 1 };
  const safeRight = right || safeLeft;
  const safeRatio = Math.max(0, Math.min(1, Number(ratio) || 0));
  return {
    r: clampByte(safeLeft.r + ((safeRight.r - safeLeft.r) * safeRatio)),
    g: clampByte(safeLeft.g + ((safeRight.g - safeLeft.g) * safeRatio)),
    b: clampByte(safeLeft.b + ((safeRight.b - safeLeft.b) * safeRatio)),
    a: clampAlpha((safeLeft.a ?? 1) + (((safeRight.a ?? 1) - (safeLeft.a ?? 1)) * safeRatio), 1)
  };
};

const withAlpha = (color, alpha = 1) => ({
  r: clampByte(color?.r),
  g: clampByte(color?.g),
  b: clampByte(color?.b),
  a: clampAlpha(alpha, color?.a ?? 1)
});

const rgbTriplet = (color) => `${clampByte(color?.r)} ${clampByte(color?.g)} ${clampByte(color?.b)}`;
const rgbaString = (color, alpha = color?.a ?? 1) => `rgba(${clampByte(color?.r)}, ${clampByte(color?.g)}, ${clampByte(color?.b)}, ${clampAlpha(alpha, 1)})`;

const relativeLuminance = (color) => {
  const transform = (channel) => {
    const normalized = clampByte(channel) / 255;
    return normalized <= 0.03928
      ? normalized / 12.92
      : ((normalized + 0.055) / 1.055) ** 2.4;
  };
  return (0.2126 * transform(color?.r)) + (0.7152 * transform(color?.g)) + (0.0722 * transform(color?.b));
};

const pickReadableTextColor = (background) => (
  relativeLuminance(background) < 0.44
    ? { r: 248, g: 250, b: 252, a: 1 }
    : { r: 15, g: 23, b: 42, a: 1 }
);

const pickVsCodeColor = (colors, ...keys) => {
  const safeColors = colors && typeof colors === 'object' ? colors : {};
  for (const key of keys) {
    const parsed = parseColorValue(safeColors[key]);
    if (parsed) return parsed;
  }
  return null;
};

const buildVsCodeAppPalette = (theme) => {
  const safeTheme = theme && typeof theme === 'object' ? theme : {};
  const colors = safeTheme.colors && typeof safeTheme.colors === 'object' ? safeTheme.colors : {};
  const isDark = String(safeTheme.type || 'dark').trim().toLowerCase() !== 'light';

  const background = pickVsCodeColor(
    colors,
    'editor.background',
    'sideBar.background',
    'activityBar.background',
    'panel.background',
    'titleBar.activeBackground'
  ) || (isDark
    ? { r: 11, g: 18, b: 32, a: 1 }
    : { r: 248, g: 250, b: 252, a: 1 });

  const foreground = pickVsCodeColor(
    colors,
    'editor.foreground',
    'foreground',
    'sideBar.foreground',
    'titleBar.activeForeground'
  ) || (isDark
    ? { r: 226, g: 232, b: 240, a: 1 }
    : { r: 15, g: 23, b: 42, a: 1 });

  const accent = pickVsCodeColor(
    colors,
    'button.background',
    'focusBorder',
    'textLink.foreground',
    'activityBarBadge.background',
    'statusBarItem.remoteBackground'
  ) || (isDark
    ? { r: 14, g: 165, b: 233, a: 1 }
    : { r: 2, g: 132, b: 199, a: 1 });

  const border = pickVsCodeColor(
    colors,
    'panel.border',
    'editorGroup.border',
    'sideBar.border',
    'contrastBorder'
  ) || mixColors(background, foreground, isDark ? 0.18 : 0.14);

  const panel = pickVsCodeColor(
    colors,
    'sideBar.background',
    'panel.background',
    'titleBar.activeBackground'
  ) || mixColors(background, foreground, isDark ? 0.08 : 0.03);

  const surface = pickVsCodeColor(
    colors,
    'editorWidget.background',
    'editorGroupHeader.tabsBackground',
    'tab.activeBackground',
    'statusBar.background'
  ) || mixColors(background, foreground, isDark ? 0.12 : 0.06);

  const gradientEnd = pickVsCodeColor(
    colors,
    'activityBar.activeBorder',
    'list.highlightForeground',
    'terminal.ansiBlue'
  ) || mixColors(accent, background, isDark ? 0.28 : 0.18);

  const editorBackground = pickVsCodeColor(colors, 'editor.background') || background;
  const editorForeground = pickVsCodeColor(colors, 'editor.foreground') || foreground;
  const selection = pickVsCodeColor(
    colors,
    'editor.selectionBackground',
    'list.activeSelectionBackground',
    'inputOption.activeBorder'
  ) || withAlpha(accent, isDark ? 0.3 : 0.22);
  const lineHighlight = pickVsCodeColor(colors, 'editor.lineHighlightBackground')
    || mixColors(editorBackground, foreground, isDark ? 0.08 : 0.04);
  const gutterBackground = pickVsCodeColor(colors, 'editorGutter.background') || editorBackground;
  const gutterForeground = pickVsCodeColor(colors, 'editorLineNumber.foreground')
    || mixColors(editorForeground, editorBackground, isDark ? 0.42 : 0.46);
  const accentForeground = pickVsCodeColor(colors, 'button.foreground') || pickReadableTextColor(accent);
  const secondary = mixColors(background, foreground, isDark ? 0.42 : 0.32);

  return {
    isDark,
    preview: `linear-gradient(135deg, ${rgbaString(background, 1)} 0%, ${rgbaString(surface, 1)} 48%, ${rgbaString(accent, 1)} 100%)`,
    previewBackground: rgbaString(background, 1),
    previewForeground: rgbaString(foreground, 1),
    primaryRgb: rgbTriplet(accent),
    primaryForegroundRgb: rgbTriplet(accentForeground),
    secondaryRgb: rgbTriplet(secondary),
    secondaryForegroundRgb: rgbTriplet(foreground),
    accentRgb: rgbTriplet(gradientEnd),
    accentForegroundRgb: rgbTriplet(pickReadableTextColor(gradientEnd)),
    backgroundRgb: rgbTriplet(background),
    surfaceRgb: rgbTriplet(surface),
    foregroundRgb: rgbTriplet(foreground),
    borderRgb: rgbTriplet(border),
    panelBg: rgbaString(panel, isDark ? 0.88 : 0.93),
    panelBorder: rgbaString(border, isDark ? 0.3 : 0.18),
    panelBorderStrong: rgbaString(accent, isDark ? 0.44 : 0.28),
    panelShadow: isDark
      ? '0 26px 50px -34px rgba(2, 6, 23, 0.88)'
      : '0 22px 44px -32px rgba(15, 23, 42, 0.24)',
    surfaceBg: rgbaString(surface, isDark ? 0.86 : 0.95),
    surfaceBorder: rgbaString(border, isDark ? 0.24 : 0.16),
    surfaceBorderHover: rgbaString(mixColors(border, accent, 0.22), isDark ? 0.36 : 0.26),
    surfaceShadow: isDark
      ? '0 12px 24px -18px rgba(2, 6, 23, 0.82)'
      : '0 10px 22px -18px rgba(15, 23, 42, 0.18)',
    surfaceShadowHover: isDark
      ? '0 16px 28px -18px rgba(14, 165, 233, 0.22)'
      : '0 14px 26px -18px rgba(2, 132, 199, 0.18)',
    focusRing: rgbaString(accent, isDark ? 0.26 : 0.16),
    gradientStart: rgbaString(accent, 1),
    gradientEnd: rgbaString(gradientEnd, 1),
    editorBackground,
    editorForeground,
    selection,
    lineHighlight,
    gutterBackground,
    gutterForeground
  };
};

const buildImportedThemeRecord = (rawTheme) => {
  if (!rawTheme || typeof rawTheme !== 'object') return null;
  const colors = Object.fromEntries(
    Object.entries(rawTheme.colors || {}).filter(([key, value]) => (
      String(key || '').trim() !== '' && typeof value === 'string' && value.trim() !== ''
    ))
  );
  const sourcePath = String(rawTheme.sourcePath || '').trim();
  const themePath = String(rawTheme.themePath || sourcePath).trim();
  const label = String(rawTheme.label || rawTheme.name || 'Imported VS Code Theme').trim();
  if (!label || !themePath) return null;

  const type = String(rawTheme.type || '').trim().toLowerCase() === 'light' ? 'light' : 'dark';
  const extensionDisplayName = String(rawTheme.extensionDisplayName || '').trim();
  const tokenColorCount = Number(rawTheme.tokenColorCount) || 0;
  const sourceLabel = extensionDisplayName
    ? extensionDisplayName
    : (String(rawTheme.sourceType || 'file').trim() === 'vsix' ? 'VSIX Extension' : 'Theme File');

  return {
    id: `vscode-${hashString(`${sourcePath}|${themePath}|${label}`)}`,
    kind: 'vscode',
    label,
    name: String(rawTheme.name || label).trim() || label,
    description: tokenColorCount > 0
      ? `${sourceLabel} • ${tokenColorCount} token groups`
      : sourceLabel,
    isDark: type !== 'light',
    type,
    sourceType: String(rawTheme.sourceType || 'file').trim() || 'file',
    sourcePath,
    themePath,
    extensionName: String(rawTheme.extensionName || '').trim(),
    extensionDisplayName,
    extensionPublisher: String(rawTheme.extensionPublisher || '').trim(),
    tokenColorCount,
    colors,
    appPalette: buildVsCodeAppPalette({ type, colors })
  };
};

const normalizeImportedThemeList = (items = []) => {
  const ordered = [];
  const deduped = new Map();
  (Array.isArray(items) ? items : []).forEach((item) => {
    const normalized = buildImportedThemeRecord(item);
    if (!normalized) return;
    if (!deduped.has(normalized.id)) {
      ordered.push(normalized.id);
    }
    deduped.set(normalized.id, normalized);
  });
  return ordered
    .map((id) => deduped.get(id))
    .filter(Boolean)
    .slice(-MAX_IMPORTED_VSCODE_THEMES);
};

const readStoredThemeSelection = () => {
  return 'ayu-dark';
};

const readStoredImportedThemes = () => {
  try {
    const raw = window.localStorage.getItem(IMPORTED_VSCODE_THEMES_STORAGE_KEY);
    if (!raw) return [];
    return normalizeImportedThemeList(JSON.parse(raw));
  } catch (_) {
    return [];
  }
};

const normalizeModelMemoryEntries = (items = []) => {
  const safeItems = Array.isArray(items) ? items : [];
  return safeItems
    .map((item, index) => {
      if (!item || typeof item !== 'object') return null;
      const id = String(item.id || `model-memory-${Date.now()}-${index}`).trim();
      const name = String(item.name || '').trim();
      if (!id || !name) return null;
      const savedAt = Number(item.savedAt);
      const predictorStandardizationRaw = item.predictorStandardization && typeof item.predictorStandardization === 'object'
        ? item.predictorStandardization
        : {};
      const standardizePredictors = normalizeRegressionStandardizePredictors(
        predictorStandardizationRaw.enabled ?? item.standardizePredictors
      );
      const standardizationStatsRaw = predictorStandardizationRaw.stats && typeof predictorStandardizationRaw.stats === 'object'
        ? predictorStandardizationRaw.stats
        : {};
      const normalizedStandardizationStats = Object.entries(standardizationStatsRaw).reduce((acc, [predictorName, stats]) => {
        const safePredictorName = String(predictorName || '').trim();
        if (!safePredictorName || !stats || typeof stats !== 'object') return acc;
        const mean = Number(stats.mean);
        const sd = Number(stats.sd);
        if (!Number.isFinite(mean) || !Number.isFinite(sd) || sd <= 0) return acc;
        acc[safePredictorName] = { mean, sd };
        return acc;
      }, {});
      const standardizedNumericPredictors = Array.from(new Set(
        (Array.isArray(predictorStandardizationRaw.numeric_predictors)
          ? predictorStandardizationRaw.numeric_predictors
          : [])
          .map((value) => String(value || '').trim())
          .filter(Boolean)
      ));
      return {
        ...item,
        id,
        name,
        mode: String(item.mode || '').trim(),
        displayMode: String(item.displayMode || '').trim(),
        equation: String(item.equation || '').trim(),
        formula: String(item.formula || '').trim(),
        responseVariable: String(item.responseVariable || '').trim(),
        predictors: Array.isArray(item.predictors) ? item.predictors.map((p) => String(p || '').trim()).filter(Boolean) : [],
        variableTypes: Array.isArray(item.variableTypes) ? item.variableTypes : [],
        selectedColumns: Array.isArray(item.selectedColumns) ? item.selectedColumns : [],
        selectedColumnsTypes: Array.isArray(item.selectedColumnsTypes) ? item.selectedColumnsTypes : [],
        datasetName: String(item.datasetName || '').trim(),
        selectedRowCount: Number.isFinite(Number(item.selectedRowCount)) ? Number(item.selectedRowCount) : 0,
        trainPercent: Number.isFinite(Number(item.trainPercent)) ? Number(item.trainPercent) : null,
        testPercent: Number.isFinite(Number(item.testPercent)) ? Number(item.testPercent) : null,
        classificationThreshold: Number.isFinite(Number(item.classificationThreshold))
          ? normalizeRegressionClassificationThreshold(item.classificationThreshold)
          : null,
        standardizePredictors,
        predictorStandardization: {
          enabled: standardizePredictors,
          method: standardizePredictors ? 'zscore_train' : 'none',
          numeric_predictors: standardizedNumericPredictors,
          stats: normalizedStandardizationStats
        },
        coefficients: Array.isArray(item.coefficients) ? item.coefficients : [],
        modelStats: item.modelStats && typeof item.modelStats === 'object' ? item.modelStats : null,
        evaluation: item.evaluation && typeof item.evaluation === 'object' ? item.evaluation : null,
        binaryMapping: item.binaryMapping && typeof item.binaryMapping === 'object'
          ? {
            class0: String(item.binaryMapping.class0 ?? '').trim(),
            class1: String(item.binaryMapping.class1 ?? '').trim()
          }
          : null,
        savedAt: Number.isFinite(savedAt) ? savedAt : Date.now()
      };
    })
    .filter(Boolean)
    .slice(0, MAX_MODEL_MEMORY_ENTRIES);
};

const readStoredModelMemoryEntries = () => {
  try {
    const raw = window.localStorage.getItem(MODEL_MEMORY_STORAGE_KEY);
    if (!raw) return [];
    return normalizeModelMemoryEntries(JSON.parse(raw));
  } catch (_) {
    return [];
  }
};

const resolveThemeOption = (themeId) => (
  BUILTIN_THEME_OPTIONS.find((themeOption) => themeOption.id === themeId)
  || BUILTIN_THEME_OPTIONS.find((themeOption) => themeOption.id === 'ayu-dark')
);

const clearImportedThemeCssVariables = (root) => {
  if (!root) return;
  IMPORTED_THEME_CSS_VARIABLES.forEach((variableName) => root.style.removeProperty(variableName));
};

const applyImportedThemeCssVariables = (root, palette) => {
  if (!root || !palette) return;
  const variableEntries = {
    '--primary-rgb': palette.primaryRgb,
    '--primary-foreground-rgb': palette.primaryForegroundRgb,
    '--secondary-rgb': palette.secondaryRgb,
    '--secondary-foreground-rgb': palette.secondaryForegroundRgb,
    '--accent-rgb': palette.accentRgb,
    '--accent-foreground-rgb': palette.accentForegroundRgb,
    '--background-rgb': palette.backgroundRgb,
    '--surface-rgb': palette.surfaceRgb,
    '--foreground-rgb': palette.foregroundRgb,
    '--border-rgb': palette.borderRgb,
    '--gradient-start': palette.gradientStart,
    '--gradient-end': palette.gradientEnd,
    '--panel-bg': palette.panelBg,
    '--panel-border': palette.panelBorder,
    '--panel-border-strong': palette.panelBorderStrong,
    '--panel-shadow': palette.panelShadow,
    '--surface-bg': palette.surfaceBg,
    '--surface-border': palette.surfaceBorder,
    '--surface-border-hover': palette.surfaceBorderHover,
    '--surface-shadow': palette.surfaceShadow,
    '--surface-shadow-hover': palette.surfaceShadowHover,
    '--focus-ring': palette.focusRing
  };

  Object.entries(variableEntries).forEach(([variableName, variableValue]) => {
    if (variableValue) {
      root.style.setProperty(variableName, String(variableValue));
    } else {
      root.style.removeProperty(variableName);
    }
  });
};

const formatTimestamp = (dateOrNum) => {
  try {
    const d = dateOrNum ? new Date(dateOrNum) : new Date();
    return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  } catch {
    return '10:07 PM';
  }
};

const formatModelDisplayName = (model = '', isCloud = false) => {
  const raw = String(model || '').trim();
  if (!raw) return 'Gemma 4 31B CLOUD';
  let clean = raw.split('/').pop().replace(/:latest$/, '');
  clean = clean.replace(/[-_]/g, ' ');
  clean = clean.replace(/\b\w/g, (c) => c.toUpperCase());
  if (isCloud && !clean.toUpperCase().includes('CLOUD')) {
    clean += ' CLOUD';
  }
  return clean;
};

const chatCodeLanguageSupport = Object.freeze({
  r: r(),
  python: python()
});

const chatCodeTokenColors = Object.freeze({
  'tok-keyword': '#c586c0',
  'tok-string': '#ce9178',
  'tok-number': '#b5cea8',
  'tok-comment': '#6a9955',
  'tok-bool': '#569cd6',
  'tok-atom': '#569cd6',
  'tok-typeName': '#4ec9b0',
  'tok-className': '#4ec9b0',
  'tok-variableName': '#dcdcaa',
  'tok-propertyName': '#9cdcfe',
  'tok-definition': '#9cdcfe',
  'tok-operator': '#d4d4d4',
  'tok-punctuation': '#808080'
});

const normalizeChatCodeLanguage = (value = '') => {
  const language = String(value || '').trim().toLowerCase();
  if (['r', 'rscript', 'rmd'].includes(language)) return 'r';
  if (['py', 'python', 'python3', 'py3'].includes(language)) return 'python';
  return '';
};

const highlightChatCode = (code = '', lang = '') => {
  const source = String(code || '');
  const support = chatCodeLanguageSupport[normalizeChatCodeLanguage(lang)];
  if (!support) return [<React.Fragment key="plain">{source}</React.Fragment>];

  const ranges = [];
  try {
    highlightTree(support.language.parser.parse(source), classHighlighter, (from, to, classes) => {
      ranges.push({ from, to, classes });
    });
  } catch {
    return [<React.Fragment key="plain">{source}</React.Fragment>];
  }

  if (ranges.length === 0) return [<React.Fragment key="plain">{source}</React.Fragment>];
  const tokens = [];
  let cursor = 0;
  ranges.forEach(({ from, to, classes }, index) => {
    if (from > cursor) tokens.push(<React.Fragment key={`plain-${index}`}>{source.slice(cursor, from)}</React.Fragment>);
    const tokenClass = String(classes || '').split(/\s+/).find((name) => chatCodeTokenColors[name]);
    tokens.push(
      <span key={`token-${index}`} style={{ color: chatCodeTokenColors[tokenClass] || '#d4d4d4', fontStyle: tokenClass === 'tok-comment' ? 'italic' : 'normal' }}>
        {source.slice(from, to)}
      </span>
    );
    cursor = to;
  });
  if (cursor < source.length) tokens.push(<React.Fragment key="plain-tail">{source.slice(cursor)}</React.Fragment>);
  return tokens;
};

const parseThoughtAndContent = (text = '') => {
  const str = String(text || '');
  const match = str.match(/<think>([\s\S]*?)<\/think>/i);
  if (match) {
    return {
      thought: match[1].trim(),
      content: str.replace(/<think>[\s\S]*?<\/think>/i, '').trim()
    };
  }
  return {
    thought: null,
    content: str
  };
};

const CopyableChatCodeBlock = ({ lang, code }) => {
  const [copied, setCopied] = useState(false);
  const highlightedCode = useMemo(() => highlightChatCode(code, lang), [code, lang]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.warn('Clipboard write failed:', error);
    }
  };

  return (
    <div className="my-2.5 rounded-xl overflow-hidden border border-zinc-800 bg-[#161616] text-left">
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-zinc-800/80 bg-[#1c1c1c] text-[10px] text-zinc-400 font-mono">
        <span className="uppercase tracking-wider font-semibold">{lang}</span>
        <button
          type="button"
          onClick={handleCopy}
          className="flex items-center gap-1 hover:text-zinc-200 transition-colors cursor-pointer"
          title={copied ? 'Copied' : 'Copy code'}
        >
          {copied ? <Check size={11} className="text-emerald-400" /> : <Copy size={11} />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre className="p-3 text-[12px] font-mono text-zinc-200 overflow-x-auto leading-relaxed">
        <code>{highlightedCode}</code>
      </pre>
    </div>
  );
};

const renderAIAnswerContent = (text) => {
  if (!text) return null;
  const parts = [];
  const regex = /```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g;
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      parts.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }
    parts.push({
      type: 'code',
      lang: match[1] || 'code',
      code: match[2].trimEnd()
    });
    lastIndex = regex.lastIndex;
  }

  // Keep the currently streaming code block highlighted before its closing fence arrives.
  if (lastIndex === 0) {
    const incompleteMatch = text.match(/```([a-zA-Z0-9_-]*)\n([\s\S]*)$/);
    if (incompleteMatch) {
      const openingIndex = incompleteMatch.index || 0;
      if (openingIndex > 0) {
        parts.push({ type: 'text', content: text.slice(0, openingIndex) });
      }
      parts.push({
        type: 'code',
        lang: incompleteMatch[1] || 'code',
        code: incompleteMatch[2].replace(/```$/, '')
      });
      lastIndex = text.length;
    }
  }

  if (lastIndex < text.length) {
    parts.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  if (parts.length === 0) {
    return <span>{text}</span>;
  }

  return parts.map((part, pIdx) => {
    if (part.type === 'text') {
      return (
        <span key={pIdx} className="whitespace-pre-wrap">
          {part.content}
        </span>
      );
    }
    return <CopyableChatCodeBlock key={pIdx} lang={part.lang} code={part.code} />;
  });
};

