  const normalizeEditorStep = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return 0;
    return Math.max(0, Math.min(40, Math.round(numeric)));
  };
  // Allows negative pixel offsets for overlay nudging (-200..200)
  const normalizeEditorOffset = (value) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return 0;
    return Math.max(-200, Math.min(200, Math.round(numeric)));
  };
  const normalizeEditorTextSize = (value, fallback = 12) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return Math.max(6, Math.min(72, Math.round(fallback)));
    return Math.max(6, Math.min(72, Math.round(numeric)));
  };
  const normalizeEditorScaleType = (value) => (
    ['auto', 'linear', 'log10'].includes(String(value || '').toLowerCase())
      ? String(value).toLowerCase()
      : 'auto'
  );
  const normalizeEditorTickMode = (value) => (
    ['auto', 'count', 'interval'].includes(String(value || '').toLowerCase())
      ? String(value).toLowerCase()
      : 'auto'
  );
  const normalizeEditorTickCount = (value, fallback = 6) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return Math.max(2, Math.min(40, Math.round(fallback)));
    return Math.max(2, Math.min(40, Math.round(numeric)));
  };
  const normalizeEditorNumericText = (value, { positive = false } = {}) => {
    const raw = String(value ?? '').trim();
    if (!raw) return '';
    const numeric = Number(raw);
    if (!Number.isFinite(numeric)) return '';
    if (positive && numeric <= 0) return '';
    return String(numeric);
  };
  const resolveEditorTickModeFromInterval = (intervalValue, fallbackMode = 'auto') => {
    const normalizedInterval = normalizeEditorNumericText(intervalValue, { positive: true });
    if (normalizedInterval) return 'interval';
    return normalizeEditorTickMode(fallbackMode);
  };

  const openCellColorPicker = (rowIndex, columnName, targetElement) => {
    const rect = targetElement.getBoundingClientRect();
    setCellColorPicker({
      x: rect.left,
      y: rect.bottom + window.scrollY,
      rowIndex,
      columnName
    });
  };

  const handleSetCellColor = (color) => {
    if (!cellColorPicker) return;
    const { rowIndex, columnName } = cellColorPicker;
    setCellColorStyles(prev => ({
      ...prev,
      [`${rowIndex}::${columnName}`]: color ? { backgroundColor: color } : undefined
    }));
    setCellColorPicker(null);
  };
  const normalizeHorizontalPosition = (value) => (
    ['left', 'center', 'right'].includes(String(value)) ? String(value) : 'center'
  );
  const normalizeVerticalPosition = (value) => (
    ['up', 'center', 'down'].includes(String(value)) ? String(value) : 'center'
  );
  const normalizePlotKey = (value) => {
    const key = String(value || '').trim().toLowerCase();
    return key || '';
  };
  const normalizeLinearRegressionVariant = (value) => (
    String(value || '').trim().toLowerCase() === 'multiple' ? 'multiple' : 'simple'
  );
  const resolvedLinearRegressionVariant = normalizeLinearRegressionVariant(linearRegressionVariant);
  const getLinearRegressionDisplayLabel = (regressionResult = null, fallbackVariant = resolvedLinearRegressionVariant) => {
    const explicitVariant = String(regressionResult?.regression_linear_variant || '').trim().toLowerCase();
    const inferredVariant = Array.isArray(regressionResult?.predictors) && regressionResult.predictors.length > 1
      ? 'multiple'
      : 'simple';
    const variant = normalizeLinearRegressionVariant(
      explicitVariant || (regressionResult ? inferredVariant : fallbackVariant)
    );
    return variant === 'multiple' ? 'Multiple Linear Regression' : 'Simple Linear Regression';
  };
  const getRegressionDisplayLabel = (regressionResult = null, fallbackVariant = resolvedLinearRegressionVariant) => (
    regressionResult?.mode === 'regression_linear'
      ? getLinearRegressionDisplayLabel(regressionResult, fallbackVariant)
      : regressionResult?.mode === 'regression_ordinal_logistic'
        ? 'Ordinal Logistic Regression'
        : 'Logistic Regression'
  );
