  const [modelDetectStatus, setModelDetectStatus] = useState({});
  const [modelFilterQuery, setModelFilterQuery] = useState('');
  const [openCodeAuthStatus, setOpenCodeAuthStatus] = useState({ loading: false, connected: false, error: '' });
  const [isOpenCodeSettingsOpen, setIsOpenCodeSettingsOpen] = useState(false);

  const handleCheckOpenCodeAuth = async () => {
    setOpenCodeAuthStatus((previous) => ({ ...previous, loading: true, error: '' }));
    try {
      const result = await window.electronAPI?.getOpenCodeAuthStatus?.();
      setOpenCodeAuthStatus({ loading: false, connected: Boolean(result?.connected), error: result?.error || '' });
      if (result?.connected) setOpenCodeConsoleCommand('');
    } catch (error) {
      setOpenCodeAuthStatus({ loading: false, connected: false, error: error.message || 'Could not check OpenCode login.' });
    }
  };

  const handleDetectModels = async (providerId) => {
    if (providerId === 'opencode') {
      setModelDetectStatus((prev) => ({ ...prev, opencode: { loading: true, error: null, count: null } }));
      try {
        const res = await window.electronAPI?.getOpenCodeModels?.(getREditorWorkingDirectory());
        if (res?.success && Array.isArray(res.models) && res.models.length > 0) {
          setDetectedProviderModels((prev) => ({ ...prev, opencode: res.models }));
          setModelDetectStatus((prev) => ({ ...prev, opencode: { loading: false, error: null, count: res.models.length } }));
          setOpenCodeModel((current) => res.models.includes(current) ? current : res.models[0]);
        } else {
          setModelDetectStatus((prev) => ({ ...prev, opencode: { loading: false, error: res?.error || 'No OpenCode models returned.', count: 0 } }));
        }
      } catch (error) {
        setModelDetectStatus((prev) => ({ ...prev, opencode: { loading: false, error: error.message || 'OpenCode model detection failed.', count: 0 } }));
      }
      return;
    }
    if (providerId === 'codex') {
      setModelDetectStatus((prev) => ({
        ...prev,
        codex: { loading: true, error: null, count: null }
      }));
      try {
        const res = await window.electronAPI?.codexModels?.();
        if (res?.success && Array.isArray(res.models) && res.models.length > 0) {
          setDetectedProviderModels((prev) => ({ ...prev, codex: res.models }));
          setModelDetectStatus((prev) => ({ ...prev, codex: { loading: false, error: null, count: res.models.length } }));
          setREditorCodexModel((current) => res.models.includes(current) ? current : res.models[0]);
        } else {
          setModelDetectStatus((prev) => ({ ...prev, codex: { loading: false, error: res?.error || 'No Codex models returned.', count: 0 } }));
        }
      } catch (error) {
        setModelDetectStatus((prev) => ({ ...prev, codex: { loading: false, error: error.message || 'Codex model detection failed.', count: 0 } }));
      }
      return;
    }
    if (providerId === 'antigravity') {
      setModelDetectStatus((prev) => ({ ...prev, antigravity: { loading: true, error: null, count: null } }));
      try {
        const res = await window.electronAPI?.antigravityModels?.();
        if (res?.success && Array.isArray(res.models) && res.models.length > 0) {
          setDetectedProviderModels((prev) => ({ ...prev, antigravity: res.models }));
          setModelDetectStatus((prev) => ({ ...prev, antigravity: { loading: false, error: null, count: res.models.length } }));
          setREditorAntigravityModel((current) => res.models.includes(current) ? current : res.models[0]);
          setAntigravityAuthStatus({ loading: false, connected: true, message: 'Connected to Antigravity' });
        } else {
          setModelDetectStatus((prev) => ({ ...prev, antigravity: { loading: false, error: res?.error || 'No Antigravity models returned.', count: 0 } }));
          setAntigravityAuthStatus({ loading: false, connected: false, message: res?.error || 'Sign in with the Antigravity desktop app first.' });
        }
      } catch (error) {
        setModelDetectStatus((prev) => ({ ...prev, antigravity: { loading: false, error: error.message || 'Antigravity model detection failed.', count: 0 } }));
        setAntigravityAuthStatus({ loading: false, connected: false, message: error.message || 'Antigravity model detection failed.' });
      }
      return;
    }

    let host = '';
    let apiKey = '';
    if (providerId === 'ollama') {
      host = isREditorCloudServer ? rEditorCloudUrl : 'http://localhost:11434';
      apiKey = isREditorCloudServer ? rEditorCloudApiKey : '';
    } else if (providerId === 'openai') {
      host = rEditorOpenAiHost || R_EDITOR_OPENAI_DEFAULT_HOST;
      apiKey = rEditorOpenAiApiKey;
    } else if (providerId === 'opencode') {
      host = rEditorOpenCodeHost || R_EDITOR_OPENCODE_DEFAULT_HOST;
      apiKey = rEditorOpenCodeApiKey;
    } else if (providerId === 'anthropic') {
      host = rEditorAnthropicHost || R_EDITOR_ANTHROPIC_DEFAULT_HOST;
      apiKey = rEditorAnthropicApiKey;
    } else if (providerId === 'nvidia') {
      host = rEditorNvidiaHost || R_EDITOR_NVIDIA_DEFAULT_HOST;
      apiKey = rEditorNvidiaApiKey;
    } else if (providerId === 'openrouter') {
      host = rEditorOpenRouterHost || R_EDITOR_OPENROUTER_DEFAULT_HOST;
      apiKey = rEditorOpenRouterApiKey;
    } else if (providerId === 'unorouter') {
      host = rEditorUnoRouterHost || R_EDITOR_UNOROUTER_DEFAULT_HOST;
      apiKey = rEditorUnoRouterApiKey;
    }

    setModelDetectStatus((prev) => ({
      ...prev,
      [providerId]: { loading: true, error: null, count: null }
    }));

    try {
      let res;
      if (window.electronAPI?.detectProviderModels) {
        res = await window.electronAPI.detectProviderModels({ provider: providerId, host, apiKey });
      } else {
        const cleanHost = String(host || '').trim().replace(/\/+$/, '');
        let targetUrl = '';
        const headers = {};
        if (providerId === 'anthropic') {
          targetUrl = `${cleanHost || R_EDITOR_ANTHROPIC_DEFAULT_HOST}/models`;
          if (apiKey) headers['x-api-key'] = apiKey;
          headers['anthropic-version'] = '2023-06-01';
          headers['anthropic-dangerous-direct-browser-access'] = 'true';
        } else if (providerId === 'ollama') {
          targetUrl = `${cleanHost || 'http://localhost:11434'}/api/tags`;
          if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
        } else {
          const defHost = providerId === 'openrouter'
            ? R_EDITOR_OPENROUTER_DEFAULT_HOST
            : providerId === 'unorouter'
              ? R_EDITOR_UNOROUTER_DEFAULT_HOST
              : providerId === 'opencode'
                ? R_EDITOR_OPENCODE_DEFAULT_HOST
              : providerId === 'nvidia'
                ? R_EDITOR_NVIDIA_DEFAULT_HOST
                : R_EDITOR_OPENAI_DEFAULT_HOST;
          targetUrl = `${cleanHost || defHost}/models`;
          if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
        }
        const resp = await fetch(targetUrl, { headers });
        if (!resp.ok) {
          const txt = await resp.text().catch(() => '');
          let msg = `HTTP ${resp.status}`;
          try { msg = JSON.parse(txt)?.error?.message || msg; } catch { }
          throw new Error(msg);
        }
        const data = await resp.json();
        const list = Array.isArray(data) ? data : (data.data || data.models || []);
        res = {
          success: true,
          models: list.map((m) => (typeof m === 'string' ? m : (m?.id || m?.name || m?.model))).filter(Boolean)
        };
      }

      if (res?.success && Array.isArray(res.models) && res.models.length > 0) {
        setDetectedProviderModels((prev) => ({ ...prev, [providerId]: res.models }));
        setModelDetectStatus((prev) => ({
          ...prev,
          [providerId]: { loading: false, error: null, count: res.models.length }
        }));
      } else {
        const errMsg = res?.error || 'No models returned by host';
        setModelDetectStatus((prev) => ({
          ...prev,
          [providerId]: { loading: false, error: errMsg, count: 0 }
        }));
      }
    } catch (err) {
      setModelDetectStatus((prev) => ({
        ...prev,
        [providerId]: { loading: false, error: err.message || 'Detection failed', count: 0 }
      }));
    }
  };

  const [isREditorCloudServer, setIsREditorCloudServer] = useState(() => (
    window.localStorage.getItem(OLLAMA_CLOUD_ENABLED_STORAGE_KEY) === 'true'
  ));

  const [editorLanguage, setEditorLanguage] = useState(() => (
    window.localStorage.getItem('editor_language') === 'python' ? 'python' : 'r'
  ));

  const [rMarkdownMode, setRMarkdownMode] = useState(false);
  const [pythonNotebookMode, setPythonNotebookMode] = useState(() => {
    if (localStorage.getItem('editor_language') !== 'python') return false;
    try {
      const tabs = JSON.parse(localStorage.getItem('r_editor_opened_tabs') || '[]');
      const activeId = localStorage.getItem('r_editor_active_tab_id');
      const activeTab = tabs.find((tab) => tab.id === activeId) || tabs.find((tab) => tab.language === 'python') || tabs[0];
      return Boolean(
        activeTab?.documentMode === 'ipynb'
        || /\.ipynb$/i.test(String(activeTab?.path || activeTab?.name || ''))
        || findAllPythonNotebookCells(activeTab?.content || '').length > 0
      );
    } catch {
      return false;
    }
  });

  useEffect(() => {
    window.localStorage.setItem('editor_language', editorLanguage);
  }, [editorLanguage]);

  useEffect(() => {
    window.localStorage.setItem('r_markdown_mode', String(rMarkdownMode));
  }, [rMarkdownMode]);

  const editorLanguageExtension = editorLanguage === 'python' ? python() : rMarkdown();
  const isRMarkdownMode = editorLanguage === 'r' && rMarkdownMode;
  const editorFileExtension = editorLanguage === 'python'
    ? (pythonNotebookMode ? 'ipynb' : 'py')
    : (isRMarkdownMode ? 'Rmd' : 'R');
  const editorLanguageLabel = editorLanguage === 'python' ? 'Python' : 'R';

  const createLanguageWorkspace = (language) => ({
    aiSource: 'local',
    isAgentMode: true,
    localModel: '',
    ideChatInput: '',
    ideChatMessages: [{
      id: `ide-welcome-${language}`,
      role: 'assistant',
      text: `Tell me what to build in ${language === 'python' ? 'Python' : 'R'}. I will generate code with your selected AI runtime and write it into the editor.`
    }],
    idePendingChange: null,
    ollamaMode: 'chat',
    geminiEditorHistory: [],
    geminiConsoleHistory: [],
    consoleInput: '',
    consoleHistory: [],
    consoleHistoryIndex: -1,
    consoleSuggestions: [],
    consoleSuggestionIndex: 0,
    openCodeConsoleCommand: '',
    openCodeModel: '',
    openCodeSessionId: ''
  });
  const [languageWorkspaces, setLanguageWorkspaces] = useState(() => ({
    r: createLanguageWorkspace('r'),
    python: createLanguageWorkspace('python')
  }));
  const activeLanguageWorkspace = languageWorkspaces[editorLanguage];
  const updateLanguageWorkspace = (field, updater) => {
    setLanguageWorkspaces((previous) => {
      const currentWorkspace = previous[editorLanguage];
      const currentValue = currentWorkspace[field];
      const nextValue = typeof updater === 'function' ? updater(currentValue) : updater;
      return {
        ...previous,
        [editorLanguage]: { ...currentWorkspace, [field]: nextValue }
      };
    });
  };
  const openCodeConsoleCommand = activeLanguageWorkspace.openCodeConsoleCommand || '';
  const setOpenCodeConsoleCommand = (value) => updateLanguageWorkspace('openCodeConsoleCommand', value);
  const openCodeModel = activeLanguageWorkspace.openCodeModel || '';
  const setOpenCodeModel = (value) => updateLanguageWorkspace('openCodeModel', value);
  const openCodeSessionId = activeLanguageWorkspace.openCodeSessionId || '';
  const setOpenCodeSessionId = (value) => updateLanguageWorkspace('openCodeSessionId', value);
  const rEditorAISource = activeLanguageWorkspace.aiSource;
  const setREditorAISource = (value) => updateLanguageWorkspace('aiSource', value);
  const isREditorAgentMode = activeLanguageWorkspace.isAgentMode ?? (activeLanguageWorkspace.aiSource === 'agent' || true);
  const setIsREditorAgentMode = (value) => updateLanguageWorkspace('isAgentMode', value);
  const rEditorLocalModel = activeLanguageWorkspace.localModel;
  const setREditorLocalModel = (value) => updateLanguageWorkspace('localModel', value);

  const [claudeAgentSpec, setClaudeAgentSpec] = useState('');
  useEffect(() => {
    if (window.electronAPI?.getClaudeAgentSpec) {
      window.electronAPI.getClaudeAgentSpec().then((res) => {
        if (res?.success && res.spec) {
          setClaudeAgentSpec(res.spec);
        }
      }).catch((err) => {
        console.warn('[App.jsx] Could not load Claude Agent Spec:', err);
      });
    }
  }, []);

  const [showWrapperEditor, setShowWrapperEditor] = useState(false);
  const [showDocAssistant, setShowDocAssistant] = useState(false);
  const [showShapiroGuide, setShowShapiroGuide] = useState(false);
  const [showKruskalGuide, setShowKruskalGuide] = useState(false);
  const [showHomogeneityGuide, setShowHomogeneityGuide] = useState(false);
  const [showANOVAGuide, setShowANOVAGuide] = useState(false);
  const [isBiostatsModeEnabled, setIsBiostatsModeEnabled] = useState(false);
  const [isBioinformaticsModeEnabled, setIsBioinformaticsModeEnabled] = useState(false);
  const [bioinformaticsMode, setBioinformaticsMode] = useState('fastq_quality');
  const [fastqQualityTool, setFastqQualityTool] = useState('fastqc');
  const [alignmentTool, setAlignmentTool] = useState('bowtie2');
