  const [eccDnaFinderLog, setEccDnaFinderLog] = useState('');
  const [isEccDnaFinderRunning, setIsEccDnaFinderRunning] = useState(false);
  const [isEccDnaFinderInstalling, setIsEccDnaFinderInstalling] = useState(false);
  const [isEccDnaFinderInstallingDependencies, setIsEccDnaFinderInstallingDependencies] = useState(false);
  const [isEccIndexing, setIsEccIndexing] = useState(false);
  const [eccIndexLog, setEccIndexLog] = useState('');
  const [eccIndexSuccess, setEccIndexSuccess] = useState(false);
  // Batch loop state
  const [eccLoopMode, setEccLoopMode] = useState(false);
  const [eccFastqFolder, setEccFastqFolder] = useState('');
  const [eccLoopSamples, setEccLoopSamples] = useState([]);       // detected sample list
  const [eccLoopResults, setEccLoopResults] = useState([]);       // per-sample results
  const [eccLoopRunning, setEccLoopRunning] = useState(false);
  const [eccLoopProgress, setEccLoopProgress] = useState({ current: 0, total: 0, currentName: '' });
  const [dnaSeqTool, setDnaSeqTool] = useState('variant_calling');
