  const getConsoleToken = (value, caretPos) => {
    const safeValue = value ?? '';
    const pos = Number.isFinite(caretPos) ? caretPos : safeValue.length;
    const prefix = safeValue.slice(0, pos);
    const match = /[A-Za-z0-9_\.\:\`]+$/.exec(prefix);
    if (!match) return null;
    return { text: match[0], start: pos - match[0].length, end: pos };
  };

  const updateConsoleSuggestions = (value = rConsoleInput, caretPos, options = {}) => {
    const force = Boolean(options?.force);
    const token = getConsoleToken(value, caretPos);
    const query = String(token?.text || '').replace(/`/g, '').toLowerCase();
    if (!force && (!token || query.length < 2)) {
      setRConsoleSuggestions([]);
      setRConsoleSuggestionIndex(0);
      setRConsoleSuggestionToken(null);
      return;
    }
    const matches = rConsoleSuggestionPool
      .map((item, idx) => {
        const lowered = item.label.toLowerCase();
        if (!query) return { item, rank: 2, idx };
        if (lowered.startsWith(query)) return { item, rank: 0, idx };
        if (lowered.includes(query)) return { item, rank: 1, idx };
        return null;
      })
      .filter(Boolean)
      .sort((left, right) => (
        left.rank - right.rank
        || left.item.label.length - right.item.label.length
        || left.idx - right.idx
      ))
      .slice(0, 12)
      .map(({ item }) => item);
    if (!matches.length) {
      setRConsoleSuggestions([]);
      setRConsoleSuggestionIndex(0);
      setRConsoleSuggestionToken(null);
      return;
    }
    setRConsoleSuggestions(matches);
    setRConsoleSuggestionIndex(0);
    setRConsoleSuggestionToken(token || { text: '', start: Number.isFinite(caretPos) ? caretPos : String(value || '').length, end: Number.isFinite(caretPos) ? caretPos : String(value || '').length });
  };

  const applyConsoleSuggestion = (item) => {
    if (!item) return;
    const inputEl = consoleInputRef.current;
    const token = rConsoleSuggestionToken || getConsoleToken(rConsoleInput, inputEl?.selectionStart);
    if (!token) return;
    const before = rConsoleInput.slice(0, token.start);
    const after = rConsoleInput.slice(token.end);
    const shouldAppendParens = item.kind === 'function' && !/^\s*\(/.test(after);
    const insertText = item.insertText || (shouldAppendParens ? `${item.label}()` : item.label);
    const cursorOffset = Number.isFinite(item.cursorOffset)
      ? Math.max(0, Math.min(insertText.length, item.cursorOffset))
      : (shouldAppendParens ? Math.max(0, insertText.length - 1) : insertText.length);
    const nextValue = `${before}${insertText}${after}`;
    setRConsoleInput(nextValue);
    setRConsoleSuggestions([]);
    setRConsoleSuggestionIndex(0);
    setRConsoleSuggestionToken(null);
    requestAnimationFrame(() => {
      if (!consoleInputRef.current) return;
      const newPos = before.length + cursorOffset;
      consoleInputRef.current.focus();
      consoleInputRef.current.setSelectionRange(newPos, newPos);
    });
  };

